import math
import re


def fit_vocab_in_fold(train_docs):
    n = len(train_docs)
    df = {}
    for d in train_docs:
        for w in set(re.findall(r'[a-z]+', d.lower())):
            df[w] = df.get(w, 0) + 1
    vocab = sorted(df)
    return {'vocab': vocab, 'idf': {w: math.log((1 + n) / (1 + df[w])) + 1 for w in vocab}}


def transform(test_docs, model):
    col = {w: j for j, w in enumerate(model['vocab'])}
    rows = []
    for d in test_docs:
        r = [0.0] * len(col)
        for w in re.findall(r'[a-z]+', d.lower()):
            if w in col:
                r[col[w]] += model['idf'][w]
        n = math.sqrt(sum(x * x for x in r))
        rows.append([x / n for x in r] if n > 0 else r)
    return rows

