import math
import re
import statistics


def mask_entities(text, names):
    for name in sorted(names, key=len, reverse=True):
        text = re.sub(r'\b' + re.escape(name) + r'\b', 'NAME', text, flags=re.IGNORECASE)
    return text


def masking_effect(scores_raw, scores_masked):
    d = [a - b for a, b in zip(scores_raw, scores_masked)]
    return statistics.fmean(d), statistics.stdev(d) / math.sqrt(len(d))

